mapper.select:
SELECT id, workspace_id, message_id, tool_name, status, arguments_json,
       result_json, executed_by_user_id, executed_at, idempotency_key,
       created_at, updated_at
FROM ai_chat_tool_call
WHERE workspace_id = #{workspaceId}
  AND message_id = #{messageId}
  AND id = #{id}

SELECT tc.id, tc.workspace_id, tc.message_id, m.session_id,
       m.author_user_id AS requested_by_user_id, tc.tool_name, tc.status,
       tc.arguments_json, tc.result_json, tc.executed_by_user_id, tc.executed_at,
       tc.idempotency_key, tc.created_at, tc.updated_at
FROM ai_chat_tool_call tc
JOIN ai_chat_message m
  ON m.workspace_id = tc.workspace_id AND m.id = tc.message_id
WHERE tc.workspace_id = #{workspaceId}
  AND m.session_id = #{sessionId}
  AND tc.id = #{id}

mapper.update:
UPDATE ai_chat_tool_call
SET status = #{status},
    result_json = #{resultJson,jdbcType=VARCHAR},
    executed_by_user_id = #{executedByUserId},
    executed_at = CURRENT_TIMESTAMP(6)
WHERE workspace_id = #{workspaceId}
  AND message_id = #{messageId}
  AND id = #{id}
  AND status = 'proposed'
